import 'package:flutter/material.dart';import 'api.dart';
class WalletPage extends StatefulWidget{const WalletPage({super.key});@override State<WalletPage> createState()=>_WalletPageState();}class _WalletPageState extends State<WalletPage>{late Future<Map<String,dynamic>> data;@override void initState(){super.initState();data=ApiClient.instance.wallet();}void refresh()=>setState(()=>data=ApiClient.instance.wallet());@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('DADO Wallet')),body:FutureBuilder<Map<String,dynamic>>(future:data,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:FilledButton(onPressed:refresh,child:const Text('Повторить')));final w=s.data!;final tx=(w['transactions'] as List?)??[];return RefreshIndicator(onRefresh:()async=>refresh(),child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Доступный баланс'),const SizedBox(height:8),Text('${w['balance']} ${w['currency']}',style:const TextStyle(fontSize:34,fontWeight:FontWeight.w900)),const SizedBox(height:16),Row(children:[Expanded(child:FilledButton.icon(onPressed:()=>showDialog(context:context,builder:(_)=>const AlertDialog(title:Text('Пополнение'),content:Text('Пополнение будет запущено через подключенный эквайринг. Данные карты DADO не хранит.'))),icon:const Icon(Icons.add),label:const Text('Пополнить'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:refresh,icon:const Icon(Icons.refresh),label:const Text('Обновить')))]))])),const SizedBox(height:18),const Text('История операций',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),if(tx.isEmpty)const Padding(padding:EdgeInsets.all(24),child:Center(child:Text('Операций пока нет'))),...tx.map((x)=>ListTile(leading:Icon((x['amount'] as num? ??0)>=0?Icons.south_west:Icons.north_east),title:Text(x['type']??'Операция'),subtitle:Text(x['status']??''),trailing:Text('${x['amount']} ${w['currency']}')))]);}}));}
